/// <summary>
/// MPJ_13564_AutoGeneratePaym
/// Batch controller class extends SysOperationServiceController
/// </summary>
[
    SysOperationJournaledParametersAttribute(true)
]
public class METCustAutoGeneratePaymController extends SysOperationServiceController
{
}

Method.Source:
    /// <summary>
    /// MPJ_13564_AutoGeneratePaym
    /// Caption visible
    /// </summary>
    protected void new()
    {
        super();

        this.parmClassName(classStr(METCustAutoGeneratePaymService));
        this.parmMethodName(methodStr(METCustAutoGeneratePaymService, processOperation));
        this.parmExecutionMode(SysOperationExecutionMode::Synchronous);
        this.parmDialogCaption("@MET:CustAutoGeneratePaymGenerate");
    }

/// <summary>
/// MPJ_13564_AutoGeneratePaym
/// Automatically populates the batch text required by user before submitting to batch
/// </summary>
/// <returns>caption</returns>
public ClassDescription caption()
{
    return "@MET:CustAutoGeneratePaymGenerate";
}

    /// <summary>
    /// MPJ_13564_AutoGeneratePaym
    /// Main method required to run the opration
    /// </summary>
    /// <param name = "args">Args</param>
    public static void main(Args args)
    {
        METCustAutoGeneratePaymController controller;

        controller = new METCustAutoGeneratePaymController();
        controller.parmArgs(args);

        controller.startOperation();
        
    }

/// <summary>
/// MPJ_2864 - kscerri - 22/03/2021
/// BP to have a constructor for new controller.
/// </summary>
/// <returns>Controller instance</returns>
public static METCustAutoGeneratePaymController construct()
{
    return new METCustAutoGeneratePaymController();
}
